<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'
import { ref } from 'vue'
import ConfirmDialog from '../../Components/ConfirmDialog.vue'
defineProps<{broadcasts:{data:any[];total:number}}>()
const confirmOpen=ref(false)
const form=useForm({message:'',audience:'all',activity_category:'active',single_user_id:'',recipient_text:'',recipients:[] as string[],throttle_ms:500,max_retries:3,confirmed:false})
const preview=()=>form.message.trim()
const submit=()=>{form.recipients=form.audience==='selected'?form.recipient_text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean):[];confirmOpen.value=true}
const send=()=>{form.confirmed=true;if(form.audience==='single'){form.transform(()=>({user_id:form.single_user_id,message:form.message})).post('/broadcasts/send-one');return}form.post('/broadcasts')}
const progress=(b:any)=>Number(b.total)>0?Math.round(Number(b.sent||0)/Number(b.total)*100):0
</script>
<template><Head title="ارسال پیام"/><v-container fluid class="pa-6 broadcast-page"><div class="d-flex align-center justify-space-between flex-wrap ga-3 mb-5"><div><h1 class="text-h4">ارسال پیام مدیریتی</h1><div class="text-medium-emphasis">ارسال تکی، گروهی و بر اساس دسته فعالیت کاربران</div></div><v-chip color="info" variant="tonal" prepend-icon="mdi-shield-check">ارسال با Server Notice</v-chip></div>
<v-row><v-col cols="12" lg="5"><v-card rounded="xl" class="pa-5"><v-card-title class="px-0">ساخت پیام جدید</v-card-title><v-form @submit.prevent="submit"><v-textarea v-model="form.message" label="متن پیام" counter="4000" rows="5" auto-grow/><v-select v-model="form.audience" label="نوع مخاطب" :items="[{title:'همه کاربران فعال',value:'all'},{title:'دسته‌بندی فعالیت',value:'category'},{title:'فهرست انتخابی',value:'selected'},{title:'یک کاربر مشخص',value:'single'}]"/><v-select v-if="form.audience==='category'" v-model="form.activity_category" label="دسته فعالیت" :items="[{title:'بسیار فعال',value:'heavy_active'},{title:'فعال',value:'active'},{title:'کم‌فعال',value:'low_active'},{title:'غیرفعال',value:'dormant'},{title:'مشکوک',value:'suspicious'}]"/><v-textarea v-if="form.audience==='selected'" v-model="form.recipient_text" label="شناسه کاربران (هر شناسه در یک خط)" rows="3" hint="برای ارسال به چند کاربر، هر Matrix ID را در یک خط وارد کنید." persistent-hint/><v-text-field v-if="form.audience==='single'" v-model="form.single_user_id" label="شناسه کامل کاربر" placeholder="@user:example.org"/><v-divider class="my-4"/><div class="text-subtitle-2 mb-2">تنظیمات صف ارسال</div><v-row><v-col cols="6"><v-text-field v-model.number="form.throttle_ms" type="number" min="100" max="60000" label="فاصله ارسال (ms)"/></v-col><v-col cols="6"><v-text-field v-model.number="form.max_retries" type="number" min="0" max="10" label="حداکثر تلاش مجدد"/></v-col></v-row><v-card variant="tonal" rounded="lg" class="pa-3 mb-4"><div class="text-caption text-medium-emphasis mb-1">پیش‌نمایش پیام</div><div class="text-body-1" style="white-space:pre-wrap">{{ preview()||'متن پیام اینجا نمایش داده می‌شود.' }}</div></v-card><v-btn type="submit" color="primary" block :disabled="!form.message.trim()||(form.audience==='single'&&!/^@[^\s]+:[^\s]+$/.test(form.single_user_id))||(form.audience==='selected'&&!form.recipient_text.trim())" :loading="form.processing" prepend-icon="mdi-send">بررسی و ادامه</v-btn></v-form></v-card></v-col>
<v-col cols="12" lg="7"><div class="d-flex align-center justify-space-between mb-3"><h2 class="text-h6">تاریخچه ارسال</h2><v-chip size="small" variant="tonal">{{ broadcasts.total }} مورد</v-chip></div><div v-if="!broadcasts.data.length" class="empty-history"><v-icon size="44" color="disabled">mdi-bullhorn-outline</v-icon><div class="text-h6 mt-3">هنوز ارسالی ثبت نشده است</div><div class="text-body-2 text-medium-emphasis">پس از ایجاد اولین پیام، وضعیت و گزارش گیرندگان اینجا نمایش داده می‌شود.</div></div><TransitionGroup v-else name="broadcast-list" tag="div" class="d-flex flex-column ga-3"><v-card v-for="b in broadcasts.data" :key="b.id" rounded="xl" class="pa-4 broadcast-card" :href="'/broadcasts/'+b.id"><div class="d-flex justify-space-between align-start ga-3"><div class="min-w-0"><div class="text-subtitle-1 font-weight-bold">ارسال #{{ b.id }}</div><div class="text-body-2 text-medium-emphasis text-truncate mt-1">{{ b.message }}</div></div><v-chip size="small" :color="b.status==='completed'?'success':b.status==='failed'?'error':b.status==='sending'?'info':'warning'" variant="tonal">{{ b.status }}</v-chip></div><v-progress-linear :model-value="progress(b)" height="8" rounded class="my-3"/><div class="d-flex justify-space-between text-caption text-medium-emphasis"><span>{{ b.sent||0 }} از {{ b.total||0 }} ارسال شده</span><span>{{ progress(b) }}%</span></div><div class="text-caption text-medium-emphasis mt-2">{{ b.created_at }}</div></v-card></TransitionGroup></v-col></v-row></v-container>
<ConfirmDialog v-model="confirmOpen" title="تأیید نهایی ارسال پیام" :message="(form.audience==='single'?'پیام برای '+form.single_user_id+' ارسال می‌شود. ':form.audience==='all'?'پیام برای همه کاربران فعال در صف ارسال قرار می‌گیرد. ':form.audience==='category'?'پیام برای دسته '+form.activity_category+' در صف قرار می‌گیرد. ':'پیام برای فهرست کاربران انتخاب‌شده در صف قرار می‌گیرد. ')+'این عملیات قابل بازگشت نیست. متن: '+preview()" confirm-text="تأیید و ارسال" danger @confirm="send"/></template>
<style scoped>
.broadcast-card{transition:transform .22s ease,box-shadow .22s ease}
.broadcast-card:hover{transform:translateY(-2px);box-shadow:0 9px 24px rgba(0,0,0,.10)}
.empty-history{min-height:220px;border:1px dashed rgba(var(--v-border-color),var(--v-border-opacity));border-radius:18px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px}
.broadcast-list-enter-active,.broadcast-list-leave-active{transition:all .22s ease}
.broadcast-list-enter-from,.broadcast-list-leave-to{opacity:0;transform:translateY(8px)}
@media(prefers-reduced-motion:reduce){.broadcast-card,.broadcast-list-enter-active,.broadcast-list-leave-active{transition:none}.broadcast-card:hover{transform:none}}
</style>
